<!DOCTYPE html>
<html lang="en">
<head>
	<meta charset="UTF-8" />
	<meta name="viewport" content="width=device-width, initial-scale=1.0" />
	<title>HMS | Hospital Management System</title>
	<link rel="preconnect" href="https://fonts.googleapis.com" />
	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
	<link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@600;700;800&display=swap" rel="stylesheet" />
		<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" />
	<style>
		:root {
			--ink: #ffffff;
			--muted: #bdc8db;
			--line: #2c4266;
			--panel: #142b50;
			--canvas: #0b1d3a;
			--teal: #d9a92e;
			--teal-dark: #b98919;
			--mint: #173866;
			--blue: #e4b93c;
			--sky: #183b6d;
			--red: #e06b70;
			--rose: #442d4e;
			--gold: #edbd3f;
			--butter: #3e351f;
			--shadow: 0 10px 26px rgba(0, 0, 0, 0.2);
		}

		* { box-sizing: border-box; }
		html { scrollbar-width: thin; scrollbar-color: var(--gold) var(--canvas); scroll-behavior: smooth; }
		::-webkit-scrollbar { width: 10px; height: 10px; }
		::-webkit-scrollbar-track { background: var(--canvas); }
		::-webkit-scrollbar-thumb { background: var(--gold); border: 2px solid var(--canvas); border-radius: 999px; }
		::-webkit-scrollbar-thumb:hover { background: var(--gold); }
		::-webkit-scrollbar-corner { background: var(--canvas); }
		body { margin: 0; background: var(--canvas); color: var(--ink); font: 14px 'DM Sans', sans-serif; }
		button { font: inherit; }
		button, a, input, label[for], .quick { cursor: pointer; }
		.app { display: flex; min-height: 100vh; }
		.sidebar { width: 228px; flex: 0 0 228px; background: #fff; border-right: 1px solid var(--line); display: flex; flex-direction: column; padding: 20px 12px 16px; }
		.brand { display: flex; align-items: center; gap: 9px; padding: 0 11px 21px; }
		.brand-mark { width: 39px; height: 39px; border-radius: 8px; background: var(--teal); color: #fff; display: grid; place-items: center; }
		.brand-mark i { width: 24px; height: 24px; stroke-width: 2.7; }
		.brand strong { display: block; font: 800 22px 'Manrope', sans-serif; letter-spacing: -1px; }
		.brand small { display: block; color: var(--teal); font-size: 6.5px; font-weight: 700; white-space: nowrap; }
		.nav { display: grid; gap: 3px; }
		.nav a { display: flex; align-items: center; gap: 15px; min-height: 38px; padding: 0 13px; border-radius: 7px; color: #294366; text-decoration: none; font-size: 13px; font-weight: 500; }
		.nav a i { width: 17px; height: 17px; stroke-width: 2.4; }
		.nav a.active { color: #fff; background: var(--teal); box-shadow: 0 5px 10px rgba(7, 131, 101, .14); }
		.side-motto { margin-top: auto; padding: 22px 4px 4px; text-align: center; color: var(--teal); font-weight: 700; font-size: 14px; line-height: 1.1; }
		.side-motto i { width: 82px; height: 52px; display: block; margin: 0 auto 9px; stroke-width: 1.1; }
		.main { min-width: 0; flex: 1; padding: 16px 24px 28px; }
		.topbar { height: 43px; display: flex; align-items: center; gap: 24px; margin-bottom: 14px; }
		.menu-toggle { display: none; color: #526b85; border: 0; background: none; padding: 3px; cursor: pointer; }
		.menu-toggle i { width: 17px; height: 17px; }
		.sidebar-close { display: none; }
		.search { width: auto; flex: 1; height: 40px; display: flex; align-items: center; gap: 11px; padding: 0 15px; border: 1px solid #dce8ef; border-radius: 10px; background: #fff; color: #6b8297; box-shadow: 0 4px 12px rgba(31, 69, 91, .06); transition: border-color .2s ease, box-shadow .2s ease; }
		.search:focus-within { border-color: #20a0a6; box-shadow: 0 0 0 3px rgba(8, 127, 140, .14); }
		.search i { width: 19px; height: 19px; stroke-width: 2.2; } .search input { width: 100%; border: 0; outline: 0; background: transparent; color: var(--ink); font-size: 13px; }
		.search input::placeholder { color: #8393a6; }
		.top-actions { display: flex; align-items: center; gap: 16px; margin-left: auto; }
		.icon-button { position: relative; border: 0; background: none; color: #627991; cursor: pointer; padding: 2px; }
		.icon-button i { width: 20px; height: 20px; }
		.topbar .menu-toggle, .topbar .icon-button, .topbar .profile > i, .topbar .search > i { display: grid; place-items: center; align-items: center; justify-items: center; padding-top: 2px; line-height: 1; box-sizing: border-box; }
		.topbar .menu-toggle { display: none; }
		.badge { position: absolute; top: -6px; right: -7px; min-width: 15px; height: 15px; padding: 0 3px; border-radius: 9px; background: #ef3d4e; color: white; font-size: 9px; display: grid; place-items: center; }
		.profile { display: flex; align-items: center; gap: 9px; }
		.avatar { width: 40px; height: 40px; border: 2px solid var(--gold); border-radius: 50%; background: #294b76; color: #fff; display: grid; place-items: center; }
		.avatar i { width: 23px; height: 23px; display: grid; place-items: center; padding-left: 2px; box-sizing: border-box; font-size: 20px; }
		.profile-info strong, .profile-info small { display: block; } .profile-info strong { font-size: 11px; } .profile-info small { margin-top: 2px; font-size: 9px; color: var(--muted); }
		.profile > i { width: 15px; margin-left: 14px; color: #36567b; }
		.hero-row { display: grid; grid-template-columns: minmax(0, 1fr) 258px; gap: 11px; }
		.hero { min-height: 178px; padding: 34px 32px; border-radius: 9px; overflow: hidden; position: relative; background: linear-gradient(90deg, rgba(222, 247, 245, .98) 0%, rgba(237, 246, 248, .87) 48%, rgba(226, 240, 246, .2)), url('https://images.unsplash.com/photo-1586773860418-d37222d8fce3?auto=format&fit=crop&w=1100&q=80') right center / cover; }
		.hero h1 { margin: 0 0 6px; font: 800 28px 'Manrope', sans-serif; letter-spacing: -1px; }
		.hero p { width: 330px; margin: 0; color: #526b83; font-size: 16px; line-height: 1.35; }
		.quote { margin-top: 16px; padding-left: 12px; border-left: 3px solid var(--teal); color: #526b83; font-size: 13px; }
		.date-card { border: 1px solid #e5edf2; border-radius: 9px; background: white; padding: 17px 20px; box-shadow: var(--shadow); }
		.date-head { display: flex; gap: 15px; align-items: flex-start; position: relative; border-bottom: 1px solid var(--line); padding-bottom: 15px; }
		.date-head i { width: 31px; height: 31px; color: var(--teal); stroke-width: 2.2; }
		.date-head small { display: block; color: #718198; font-size: 12px; } .date-head strong { display: block; font: 700 19px 'Manrope', sans-serif; margin-top: 2px; }
		.date-note { margin: 17px 0 0; color: #60718a; text-align: center; line-height: 1.55; font-size: 12px; }
		.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-top: 14px; }
		.stat { min-height: 88px; border-radius: 8px; display: flex; align-items: center; gap: 14px; padding: 15px 18px; }
		.stat.mint { background: var(--mint); } .stat.sky { background: var(--sky); } .stat.rose { background: var(--rose); } .stat.butter { background: var(--butter); }
		.stat-icon { width: 43px; height: 43px; border-radius: 50%; display: grid; place-items: center; flex: 0 0 43px; }
		.stat-icon i { width: 23px; height: 23px; } .mint .stat-icon { color: #087f8c; background: #c9eceb; } .sky .stat-icon { color: #2d74d0; background: #cfe1fb; } .rose .stat-icon { color: #e45b62; background: #ffd9d7; } .butter .stat-icon { color: #e3a12a; background: #ffe8b2; }
		.stat strong { display: block; font: 800 19px 'Manrope', sans-serif; } .stat label { display: block; margin-top: 3px; color: #50657c; font-size: 11px; } .growth { margin-left: auto; align-self: flex-end; font-size: 10px; color: var(--teal); white-space: nowrap; }
		.section-panel { border: 1px solid #e1ebef; border-radius: 8px; background: white; box-shadow: var(--shadow); }
		.panel-title { display: flex; justify-content: space-between; align-items: center; padding: 14px 16px 10px; font: 700 14px 'Manrope', sans-serif; }
		.panel-title i { vertical-align: middle; width: 17px; height: 17px; margin-right: 7px; color: var(--teal); }
		.panel-title a { color: #237fe4; text-decoration: none; font: 500 11px 'DM Sans', sans-serif; }
		.quick-panel { margin-top: 14px; padding-bottom: 14px; background: #f5fbfb; border-top: 3px solid #bde6e5; }
		.customize { border: 1px solid #e6edf3; background: white; border-radius: 5px; color: #647991; padding: 4px 8px; font-size: 9px; cursor: pointer; }
		.customize i { width: 11px; height: 11px; vertical-align: -2px; margin-right: 3px; }
		.quick-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 12px; padding: 0 16px; }
		.quick { min-height: 94px; border: 0; border-radius: 7px; padding: 15px 42px 15px 13px; text-align: left; color: var(--ink); position: relative; cursor: pointer; }
		.quick.mint { background: #edf9f8; color: #087f8c; } .quick.sky { background: #edf5ff; color: #2d74d0; } .quick.rose { background: #fff2f0; color: #e45b62; } .quick.violet { background: #eef2ff; color: #4262a8; } .quick.butter { background: #fff8e8; color: #e3a12a; }
		.quick i { width: 25px; height: 25px; stroke-width: 2.1; } .quick span { display: block; max-width: 90px; margin-top: 8px; color: var(--ink); font-size: 12px; line-height: 1.2; }
		.quick em { position: absolute; right: 11px; top: 50%; width: 30px; height: 30px; transform: translateY(-50%); border-radius: 9px; border: 0; background: var(--gold); display: grid; place-items: center; font-style: normal; color: #10284b; box-shadow: 0 4px 9px rgba(217, 169, 46, .28); transition: transform .2s ease, filter .2s ease; }
		.quick:hover em { transform: translateY(-50%) translateX(2px); filter: brightness(1.08); }
		.quick em i { width: 13px; height: 13px; margin: 0; color: #10284b; }
		.content-grid { display: grid; grid-template-columns: 1.1fr .9fr .9fr; gap: 14px; margin-top: 14px; }
		.content-grid > .section-panel:nth-child(1) { background: #f7fcfc; border-top: 3px solid #a9deda; }
		.content-grid > .section-panel:nth-child(2) { background: #f7faff; border-top: 3px solid #bed5f4; }
		.content-grid > .section-panel:nth-child(3) { background: #fffaf2; border-top: 3px solid #f2d59a; }
		.table-wrap { padding: 0 16px 12px; overflow: auto; } table { border-collapse: collapse; width: 100%; font-size: 11px; white-space: nowrap; } th { background: #f2f6f8; color: #5d718a; text-align: left; font-weight: 500; padding: 7px 6px; } td { padding: 8px 6px; border-bottom: 1px solid #edf1f4; color: #3b5270; } td:first-child { color: #304767; } .pill { border-radius: 5px; padding: 4px 8px; font-size: 10px; } .pill.green { color: #087f8c; background: #d8f1ef; } .pill.red { color: #d94d59; background: #ffe1df; }
		.stock td:nth-child(2) { text-align: center; } .stock td:nth-child(3) { text-align: right; }
		.notifications { padding-bottom: 8px; } .notice { display: flex; align-items: flex-start; gap: 9px; padding: 8px 16px; border-top: 1px solid #edf1f4; font-size: 11px; color: #395171; line-height: 1.3; } .notice i { width: 18px; height: 18px; flex: 0 0 18px; } .notice small { display: block; color: #8493a5; font-size: 10px; } .notice:nth-child(2) i { color: #e45b62; } .notice:nth-child(3) i { color: #2d74d0; } .notice:nth-child(4) i { color: #e3a12a; } .notice:nth-child(5) i { color: #087f8c; } .notice:nth-child(6) i { color: #4262a8; }
		footer { display: flex; justify-content: space-between; align-items: center; min-height: 37px; margin-top: 9px; padding: 0 8px; border-top: 1px solid #e7edf1; color: #64768c; font-size: 9px; } footer div { display: flex; gap: 15px; } footer a { color: #5b6d83; text-decoration: none; }
		@media (max-width: 1100px) { .sidebar { width: 200px; flex-basis: 200px; } .main { padding-left: 18px; padding-right: 18px; } .hero h1 { font-size: 23px; } .stat { padding: 10px; gap: 8px; } .stat-icon { width: 38px; height: 38px; flex-basis: 38px; } .growth { display: none; } .top-actions { margin-left: auto; } }
		@media (max-width: 820px) { .sidebar { position: fixed; z-index: 3; inset: 0 auto 0 0; transform: translateX(-100%); transition: transform .25s ease; box-shadow: 8px 0 22px rgba(0,0,0,.08); } .sidebar.open { transform: translateX(0); } .sidebar-close { position: absolute; top: 16px; right: 14px; display: grid; place-items: center; width: 30px; height: 30px; border: 1px solid #405a82; border-radius: 7px; background: #1b3964; color: #fff; font-size: 21px; line-height: 1; cursor: pointer; } .main { padding: 8px 12px 28px; } .menu-toggle { display: block; } .hero-row { grid-template-columns: 1fr; } .date-card { display: none; } .content-grid { grid-template-columns: 1fr 1fr; } .notifications { grid-column: 1 / -1; } }
		@media (max-width: 560px) { .topbar { gap: 12px; } .search { width: auto; flex: 1; } .profile-info, .profile > i { display: none; } .top-actions { gap: 12px; } .hero { min-height: 170px; padding: 23px 20px; background-position: 63% center; } .hero p { width: 240px; } .stats { grid-template-columns: repeat(2, 1fr); } .stat { min-height: 68px; } .quick-grid { grid-template-columns: repeat(2, 1fr); } .quick { min-height: 72px; } .quick:last-child { grid-column: span 2; } .content-grid { grid-template-columns: 1fr; } .notifications { grid-column: auto; } footer { align-items: flex-start; flex-direction: column; gap: 5px; padding: 9px 4px; } }

		/* Readable type scale across dashboard surfaces. */
		body { font-size: 15px; }
		.brand small { font-size: 7.5px; }
		.nav a { font-size: 14px; }
		.search input { font-size: 14px; }
		.profile-info strong { font-size: 13px; }
		.profile-info small { font-size: 11px; }
		.hero h1 { font-size: 32px; }
		.hero p { font-size: 18px; }
		.quote { font-size: 15px; }
		.date-head small { font-size: 13px; }
		.date-head strong { font-size: 22px; }
		.date-note { font-size: 13px; }
		.stat strong { font-size: 22px; }
		.stat label { font-size: 13px; }
		.growth { font-size: 11px; }
		.panel-title { font-size: 16px; }
		.panel-title a { font-size: 12px; }
		.customize { font-size: 11px; }
		.quick span { font-size: 14px; }
		table { font-size: 13px; }
		th { padding: 8px 6px; }
		td { padding: 9px 6px; }
		.pill { font-size: 11px; }
		.notice { font-size: 13px; }
		.notice small { font-size: 11px; }
		footer { font-size: 11px; }
		@media (max-width: 1100px) { .hero h1 { font-size: 29px; } }
		@media (max-width: 560px) { body { font-size: 14px; } .hero h1 { font-size: 27px; } .hero p { font-size: 16px; } .quote { font-size: 13px; } .stat strong { font-size: 19px; } .stat label { font-size: 11px; } .panel-title { font-size: 14px; } .quick span { font-size: 13px; } table { font-size: 12px; } .notice { font-size: 12px; } .content-grid, .content-grid > .section-panel { min-width: 0; } }

		/* Navy and gold visual theme. */
		body { color: #fff; background: var(--canvas); }
		.sidebar { background: #10284b; border-color: #2a4165; }
		.brand strong, .nav a, .profile-info strong, .hero h1, .stat strong, .panel-title, .quick span, td, td:first-child { color: #fff; }
		.brand small, .side-motto { color: var(--gold); }
		.nav a { color: #dbe4f2; }
		.nav a.active { color: #0b1d3a; background: var(--gold); }
		.side-motto i { color: var(--gold); }
		.menu-toggle, .icon-button { color: #dce6f4; }
		.search { border-color: #405a82; background: #142b50; color: #fff; box-shadow: 0 4px 14px rgba(0, 0, 0, .16); }
		.search:focus-within { border-color: var(--gold); box-shadow: 0 0 0 3px rgba(237, 189, 63, .18); }
		.search input { color: #fff; }
		.search input::placeholder { color: #bfcbe0; }
		.profile-info small, .date-head small, .date-note, .hero p, .quote { color: #d0daea; }
		.avatar { background: #27456d; color: var(--gold); }
		.hero { background: linear-gradient(90deg, rgba(11, 29, 58, .76) 0%, rgba(17, 45, 83, .42) 48%, rgba(13, 35, 68, .08) 100%), url('https://images.unsplash.com/photo-1586773860418-d37222d8fce3?auto=format&fit=crop&w=1100&q=85') 72% center / cover; }
		.quote { border-color: var(--gold); }
		.date-card { border-color: #f1d982; background: linear-gradient(145deg, #fffdf2 0%, #f4df9b 100%); box-shadow: 0 10px 25px rgba(0, 0, 0, .18); }
		.date-head { border-color: #e7cc72; }
		.date-head i, .date-head svg { width: 31px; height: 31px; color: #fff; background: linear-gradient(145deg, #edbd3f, #b98919); padding: 5px; border: 1px solid #f8d878; border-radius: 7px; box-shadow: 0 3px 8px rgba(11, 29, 58, .18); }
		.date-card .date-head small, .date-card .date-note { color: #5a4b2b; }
		.date-card .date-head strong { color: #10284b; }
		.panel-title i { color: var(--gold); }
		.stat.mint, .stat.sky, .stat.rose, .stat.butter { background: #142f58; border: 1px solid #2b4770; }
		.stat-icon { background: #fff !important; color: #2d74d0 !important; box-shadow: 0 3px 8px rgba(11, 29, 58, .14); }
		.stat label, .growth { color: #fff; }
		.section-panel { border-color: #2d466c; background: var(--panel); }
		.panel-title a { color: var(--gold); }
		.quick-panel { background: #10284b; border-top-color: transparent; }
		.customize { border-color: #405a82; background: #1b3964; color: #fff; }
		.quick.mint, .quick.sky, .quick.rose, .quick.violet, .quick.butter { background: var(--gold); color: #10284b; border: 1px solid #f6d36c; }
		.quick span { color: #10284b; }
		.quick em { background: #10284b; border-color: transparent; color: var(--gold); }
		.content-grid > .section-panel:nth-child(1), .content-grid > .section-panel:nth-child(2), .content-grid > .section-panel:nth-child(3) { background: #142b50; border-top-color: var(--gold); }
		table { color: #fff; }
		th { background: #1d3a64; color: #fff; }
		td { border-color: #2d466c; color: #fff; }
		.pill.green { color: #0b1d3a; background: var(--gold); }
		.pill.red { color: #fff; background: #9b4b58; }
		.notice { border-color: #2d466c; color: #fff; }
		.notice small { color: #c1cee0; }
		.notice:nth-child(2) i, .notice:nth-child(3) i, .notice:nth-child(4) i, .notice:nth-child(5) i, .notice:nth-child(6) i { color: var(--gold); }
		footer { border-color: #2d466c; color: #c1cee0; }
		footer a { color: #fff; }
		.app .fa-solid { display: inline-block; }
		.stat-icon { width: 52px; height: 52px; flex-basis: 52px; border-radius: 50%; display: grid; place-items: center; }
		.stat-icon i { width: 26px; height: 26px; display: grid; place-items: center; font-size: 24px; }
		.quick > i { width: 28px; height: 28px; display: grid; place-items: center; padding: 0; border-radius: 0; background: transparent; box-shadow: none; color: currentColor; font-size: 25px; }
		.quick em { width: 28px; height: 28px; display: grid; place-items: center; }
		.quick em i { width: 13px; height: 13px; font-size: 13px; padding: 0; color: #fff; }
		.panel-title span > i { width: 27px; height: 27px; display: inline-grid; place-items: center; padding: 6px; border-radius: 50%; background: var(--gold); color: #10284b; font-size: 14px; margin-right: 8px; vertical-align: -7px; }
		.notice > i { width: 27px; height: 27px; flex: 0 0 27px; display: grid; place-items: center; padding: 6px; border-radius: 50%; background: #294b76; color: var(--gold); font-size: 14px; box-sizing: border-box; }
		.date-head i, .date-head svg { width: 38px; height: 38px; position: absolute; top: 0; left: 0; display: grid !important; place-items: center; border-radius: 50%; padding: 8px; box-sizing: border-box; }
		.date-head > div { padding-left: 53px; }
		#patientsPage { display: none; }
		.patient-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 18px; margin: 8px 0 18px; }
		.patient-heading h1 { margin: 0; color: #fff; font: 800 30px 'Manrope', sans-serif; }
		.patient-heading p { margin: 7px 0 0; color: #bdc8db; font-size: 14px; }
		.patient-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 14px; }
		.patient-kpi { display: flex; align-items: center; gap: 12px; padding: 14px; border: 1px solid #2c4266; border-radius: 10px; background: #142b50; }
		.patient-kpi i { width: 38px; height: 38px; flex: 0 0 38px; display: grid !important; place-items: center; align-items: center; justify-items: center; border-radius: 10px; background: #fff; color: #2d74d0; font-size: 18px; line-height: 1; }
		.patient-kpi strong, .patient-kpi small { display: block; } .patient-kpi strong { color: #fff; font: 800 21px 'Manrope', sans-serif; } .patient-kpi small { margin-top: 2px; color: #bdc8db; font-size: 11px; }
