		patientsPage.querySelector('.patient-table-wrap').appendChild(patientEmpty);
		function filterPatients() { const query = patientSearch.value.trim().toLowerCase(); const department = patientFilters[0].value; const status = patientFilters[1].value; let visible = 0; patientRows.forEach((row, index) => { const matchesText = row.textContent.toLowerCase().includes(query); const matchesDepartment = !department || patientDepartments[index] === department; const matchesStatus = !status || patientStatuses[index] === status; const show = matchesText && matchesDepartment && matchesStatus; row.style.display = show ? '' : 'none'; if (show) visible += 1; }); patientEmpty.style.display = visible ? 'none' : 'block'; }
