		function openModuleAction(button) { const action = button.textContent.trim(); const page = button.closest('.module-page'); const title = page ? page.querySelector('h1').textContent : 'Module'; moduleActionTitle.textContent = action; moduleFormFields.innerHTML = (moduleFieldSets[action] || [['Details', 'details', 'text']]).map(([label, name, type]) => type === 'textarea' ? `<label>${label}<textarea name="${name}" rows="2" required></textarea></label>` : type === 'select' ? `<label>${label}<select name="${name}" required><option value="">Select option</option>${(moduleOptions[name] || ['High', 'Normal', 'Low']).map(option => `<option>${option}</option>`).join('')}</select></label>` : `<label>${label}<input name="${name}" type="${type}" required /></label>`).join(''); if (action === 'Add Doctor') { moduleActionForm.method = 'POST'; moduleActionForm.action = '{{ route('doctors.store') }}'; } moduleActionModal.dataset.module = title; moduleActionModal.classList.add('open'); moduleFormFields.querySelector('input, select, textarea')?.focus(); }
