		moduleActionForm.addEventListener('submit', event => { event.preventDefault(); const action = moduleActionTitle.textContent; const modulePage = moduleActionModal.dataset.module; const page = [...document.querySelectorAll('.module-page')].find(item => item.querySelector('h1')?.textContent === modulePage); const values = [...new FormData(moduleActionForm).values()].map(value => String(value)); const table = page?.querySelector('.module-table'); if (table) { const row = document.createElement('tr'); const cellCount = table.querySelectorAll('thead th').length; values.slice(0, Math.max(1, cellCount - 1)).forEach(value => { const cell = document.createElement('td'); cell.textContent = value; row.appendChild(cell); }); while (row.children.length < cellCount - 1) { row.appendChild(document.createElement('td')); } const statusCell = document.createElement('td'); const status = document.createElement('span'); status.className = 'module-badge'; status.textContent = 'New'; statusCell.appendChild(status); row.appendChild(statusCell); table.querySelector('tbody').appendChild(row); } else { const list = page?.querySelector('.module-list'); if (list) { const item = document.createElement('div'); item.className = 'module-list-item'; const content = document.createElement('div'); content.textContent = values[0] || action; const detail = document.createElement('small'); detail.textContent = values.slice(1).join(' · ') || 'Saved just now'; content.appendChild(detail); const badge = document.createElement('span'); badge.className = 'module-badge'; badge.textContent = 'New'; item.append(content, badge); list.prepend(item); } } const firstKpi = page?.querySelector('.module-kpi strong'); if (firstKpi && /^\d+$/.test(firstKpi.textContent.trim())) firstKpi.textContent = String(Number(firstKpi.textContent.trim()) + 1); moduleActionModal.classList.remove('open'); moduleActionForm.reset(); moduleToast.textContent = `${action} saved in the ${modulePage} module.`; moduleToast.classList.add('show'); clearTimeout(moduleToastTimer); moduleToastTimer = setTimeout(() => moduleToast.classList.remove('show'), 2600); });
		const dashboardSections = [...document.querySelector('.main').children].filter(section => section !== document.querySelector('.topbar') && section !== patientsPage && section !== appointmentsPage && section !== appointmentModal && section !== moduleActionModal && section !== moduleToast && !section.classList.contains('module-page'));
