		async function refreshDashboardStats() { try { const response = await fetch('{{ route('dashboard.stats') }}', { headers: { Accept: 'application/json' } }); if (!response.ok) return; const stats = await response.json(); Object.entries(dashboardStatElements).forEach(([key, element]) => { if (element && Number.isFinite(Number(stats[key]))) element.textContent = Number(stats[key]).toLocaleString(); }); document.querySelectorAll('.patient-kpi, .appointment-kpi, .module-kpi').forEach(card => { const label = card.querySelector('small')?.textContent.trim(); const key = moduleStatKeys[label]; const value = stats[key]; const target = card.querySelector('strong'); if (target && key && Number.isFinite(Number(value))) target.textContent = Number(value).toLocaleString(); }); } catch (error) { /* Keep the last known values if the endpoint is unavailable. */ } }
